import SwiftUI
import UIKit

struct MedMargAssets {
    static let heroImage: UIImage = {
        if let img = UIImage(named: "hero") { return img }
        if let img = UIImage(named: "login-phlebo-hero") { return img }
        if let path = Bundle.main.path(forResource: "hero", ofType: "jpg"),
           let img = UIImage(contentsOfFile: path) { return img }
        if let data = Data(base64Encoded: ""),
           let img = UIImage(data: data) { return img }
        return UIImage()
    }()

    static let templeImage: UIImage = {
        if let img = UIImage(named: "temple") { return img }
        if let img = UIImage(named: "tirupati-temple-banner") { return img }
        if let path = Bundle.main.path(forResource: "temple", ofType: "jpg"),
           let img = UIImage(contentsOfFile: path) { return img }
        if let data = Data(base64Encoded: ""),
           let img = UIImage(data: data) { return img }
        return UIImage()
    }()
}
